css:
.card {
  background: white;
  border-radius: 18px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.1);
  max-width: 350px;
  width: 100%;
  padding: 25px;
  position: relative;
  overflow: hidden;
}

.time-badge {
  position: absolute;
  top: 10px;
  right: 10px;
  background: #1a1a1a;
  color: white;
  padding: 6px 8px;
  border-radius: 50px;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  z-index: 10;
}

.clock-icon {
  width: 16px;
  height: 16px;
  border: 1.5px solid white;
  border-radius: 50%;
  position: relative;
}

.clock-icon::before {
  content: "";
  position: absolute;
  width: 1.5px;
  height: 6px;
  background: white;
  top: 2px;
  left: 50%;
  transform: translateX(-50%);
  transform-origin: bottom;
  animation: clockHand 2s infinite linear;
}

@keyframes clockHand {
  0% {
    transform: translateX(-50%) rotate(0deg);
  }
  100% {
    transform: translateX(-50%) rotate(360deg);
  }
}

.illustration {
  width: 100%;
  height: 180px;
  margin-bottom: 25px;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
}

.conveyor-belt {
  position: absolute;
  width: 100%;
  height: 70px;
  background: #e0e0e0;
  border-radius: 6px;
  overflow: hidden;
  top: 80px;
}

.conveyor-belt::before {
  content: "";
  position: absolute;
  width: 200%;
  height: 100%;
  background: repeating-linear-gradient(
    90deg,
    transparent,
    transparent 30px,
    #d0d0d0 30px,
    #d0d0d0 35px
  );
  animation: conveyorMove 3s linear infinite;
}

@keyframes conveyorMove {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-50%);
  }
}

.package {
  position: relative;
  width: 100px;
  height: 100px;
  animation: packageSlide 4s ease-in-out infinite;
  z-index: 5;
}

@keyframes packageSlide {
  0%,
  100% {
    transform: translateX(-100px);
  }
  50% {
    transform: translateX(100px);
  }
}

.box {
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  animation: boxRotate 4s ease-in-out infinite;
}

@keyframes boxRotate {
  0%,
  100% {
    transform: rotateY(0deg);
  }
  25% {
    transform: rotateY(-10deg);
  }
  75% {
    transform: rotateY(10deg);
  }
}

.box-face {
  position: absolute;
  width: 100px;
  height: 100px;
  background: white;
  border: 2px solid #ddd;
  border-radius: 6px;
}

.box-top {
  background: linear-gradient(135deg, #fff 0%, #f5f5f5 100%);
  transform: translateY(-12px);
}

.tape {
  position: absolute;
  width: 30px;
  height: 100%;
  background: #c8ff5c;
  left: 50%;
  transform: translateX(-50%);
  opacity: 0.9;
}

.tape-horizontal {
  width: 100%;
  height: 30px;
  top: 50%;
  transform: translateY(-50%);
  left: 0;
}

.content {
  position: relative;
  z-index: 2;
  transform: translateY(-30px);
}

.card-title {
  font-size: 1.25rem;
  color: #1a1a1a;
  margin-bottom: 12px;
  font-weight: 700;
}

.card-description {
  font-size: 0.8rem;
  color: #666;
  line-height: 1.4;
  margin-bottom: 25px;
  max-width: 500px;
  margin: 0;
  padding: 0;
}

.footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 15px;
  padding-top: 18px;
  border-top: 1px solid #e8e8e8;
}

.view-status-btn {
  background: white;
  color: #1a1a1a;
  border: 1.5px solid #e0e0e0;
  padding: 10px 32px;
  border-radius: 50px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
  width: 100%;
}

.view-status-btn::before {
  content: "";
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(255, 255, 255, 0.8),
    transparent
  );
  transition: left 0.5s ease;
}

.view-status-btn:hover::before {
  left: 100%;
}

.view-status-btn:hover {
  background: #1a1a1a;
  color: white;
  border-color: #1a1a1a;
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.15);
}

.view-status-btn:active {
  transform: translateY(0);
}

.status-message {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #666;
  font-size: 0.85rem;
  width: 100%;
  justify-content: center;
}

.package-icon {
  width: 24px;
  height: 24px;
  background: #f5f5f5;
  border: 1.5px solid #ddd;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.package-icon::after {
  content: "";
  width: 12px;
  height: 2px;
  background: #ddd;
}

.package-icon::before {
  content: "";
  width: 2px;
  height: 12px;
  background: #ddd;
  position: absolute;
}

@media (max-width: 768px) {
  .card {
    padding: 30px 20px;
  }

  .time-badge {
    top: 20px;
    right: 20px;
    padding: 10px 20px;
    font-size: 16px;
  }

  .illustration {
    height: 250px;
  }

  .package {
    width: 140px;
    height: 140px;
  }

  .box-face {
    width: 140px;
    height: 140px;
  }

  .card-title {
    font-size: 2rem;
  }

  .card-description {
    font-size: 1rem;
  }

  .footer {
    flex-direction: column;
    align-items: stretch;
  }

  .view-status-btn {
    width: 100%;
    text-align: center;
  }

  .status-message {
    justify-content: center;
  }
}

@media (max-width: 480px) {
  .card-title {
    font-size: 1.75rem;
  }

  .time-badge {
    font-size: 14px;
    padding: 8px 16px;
  }

  .illustration {
    height: 200px;
  }

  .package {
    width: 120px;
    height: 120px;
  }

  .box-face {
    width: 120px;
    height: 120px;
  }
}
